    // Recovery: replay
    287: 'Déjà dans un bloc sur cette chaîne.',
    288: "Déjà dans la mempool de ce backend ; en attente d'un bloc.",
    289: "Diffusée (${fee}). En attente d'un bloc.",
    290: 'Simulation : serait acceptée (${fee}).',
